    /*
     * Assign a Warehouse
     * 
     * @param	parentId	UUID
     * @param	assignment 	Warehouse 
     * @return	InboundShipment
     */
    public InboundShipment assignWarehouse( UUID parentId, Warehouse assignment ) {
	    LOGGER.info("assigning Warehouse as " + assignment.toString() );

	    InboundShipment parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Warehouse.class, assignment.getWarehouseId());

	    // ------------------------------------------
		// assign the Warehouse to the parent entity
		// ------------------------------------------ 
	    parentEntity.setWarehouse( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Warehouse
	 * 
	 * @param	parentId		UUID
	 * @return	InboundShipment
	 */
	public InboundShipment unAssignWarehouse( UUID parentId ) {
		InboundShipment parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Warehouse on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Warehouse on the parent entithy
		// ------------------------------------------     
	    parentEntity.setWarehouse(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


